CREATE TABLE connection_validations(workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_revision INTEGER NOT NULL,validated_at TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(workspace_id,connection_id));
CREATE TABLE connection_snapshots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_revision INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL,cursor_json TEXT NOT NULL,gaps_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,name TEXT NOT NULL,facts_json TEXT NOT NULL,UNIQUE(snapshot_id,kind,source_id));
CREATE TABLE connection_adoptions(workspace_id TEXT NOT NULL,connection_id TEXT NOT NULL,kind TEXT NOT NULL,source_id TEXT NOT NULL,target_id TEXT,reviewed_name TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(workspace_id,connection_id,kind,source_id));
